git rev-parse hotfix/BKG-82 && git diff --stat main hotfix/BKG-82 && rm -rf /tmp/wt && git worktree add -q /tmp/wt hotfix/BKG-82 && cd /tmp/wt && bash tools/check 2>&1 | tail -15; ls spec; 
t=$(mktemp -u); BOOKINGS=$t bash src/book.sh a 2026-01-05 09:00 10:00 x; BOOKINGS=$t bash src/book.sh a 2026-01-05 09:30 10:30 y; echo rc=$?; cat -A $t; 
# pre-existing file without header / empty file
: > $t.e; BOOKINGS=$t.e bash src/book.sh a 2026-01-05 09:00 10:00 x; cat $t.e; cd /app; git worktree remove --force /tmp/wt; git status --short
